clear; clc;

load("SP26_SchedulingData.mat")

% Keep only N students
studentDataN = studentData(studentData.seatStatus=="N",:);

% Keep the original course list
uniqueStudentsN = unique(studentDataN.studentIDs);

[S,numStudents,numCourses] = buildStudentMatrix(studentDataN, uniqueStudentsN, uniqueTrueIDs);

[F,numFaculty] = buildFacultyMatrix(courseDataFiltered, uniqueFaculty, uniqueTrueIDs);

disp('S=') %[output:4c958818]
disp(S) %[output:93f11269]

size(S) %[output:6564ad5e]

disp('F=') %[output:4db65ef7]
disp(F) %[output:9c4d5262]


coursePattern = extractMeetingPatterns(courseDataFiltered,uniqueTrueIDs);

fprintf("\nMeeting Pattern Summary\n") %[output:1605846c]

tabulate(categorical(coursePattern)) %[output:8e51f49c]


slotTable = buildSlotTable();

Conflict = buildConflictMatrix(slotTable);

checkConflictMatrix(slotTable,Conflict); %[output:43a19031]


disp(slotTable) %[output:32d6fba6]
disp(Conflict) %[output:9dc08001]

fprintf("Number of conflicting slot pairs = %d\n", nnz(triu(Conflict,1))); %[output:030669e0]


%% Optimization Model
assignmentProb = optimproblem;

% CONSTANTS
capacity = 25;
%numTimeSlots = height(slotTable);
numTimeSlots = 58;

uStudents = ones(numStudents,1);
uFaculty  = ones(numFaculty,1);

M = capacity*ones(numCourses,1);
classLoads = sum(S)';

% VARIABLES
P = optimvar('P',numCourses,1,'Type','integer','LowerBound',0);

A = optimvar('A',numStudents,numTimeSlots,'Type','integer','LowerBound',0);

B = optimvar('B',numFaculty,numTimeSlots,'Type','integer','LowerBound',0);

psi = optimvar('psi',numStudents,numTimeSlots,'Type','integer','LowerBound',0);

T = optimvar('T',numCourses,numTimeSlots,'Type','integer','LowerBound',0,'UpperBound',1);

%% Build ranking matrix R from S
% 0 = not enrolled
% 1 = least preferred
% 4 = most preferred

R = zeros(size(S));

%rng('shuffle')

for i = 1:numStudents

    courses = find(S(i,:));

    n = length(courses);

    if n == 0
        continue;
    end

    % Randomly assign ranks 1,...,n
    R(i,courses) = randperm(n);

end

disp('R=') %[output:758adbc0]
disp(R) %[output:3ebd7fe0]

NR = R;
NR(R==1) = 2;
NR(R==2) = 4;
NR(R==3) = 6;
NR(R==4) = 7;
disp('NR =') %[output:8afbe5f3]
disp(NR) %[output:9b3de25c]

% indicator vectors
is50MWF  = (coursePattern=="50MWF");
is50MTWF = (coursePattern=="50MTWF");
is50MTWRF = (coursePattern=="50MTWTHF");

is80MW   = (coursePattern=="80MW");
is80MWF  = (coursePattern=="80MWF");


is110MW  = (coursePattern=="110MW");
is110MWF = (coursePattern=="110MWF");


is170MW  = (coursePattern=="170MW");
is170M   = (coursePattern=="170M");
is170W   = (coursePattern=="170W");
is170F   = (coursePattern=="170F");


is80TR   = (coursePattern=="80TTH");
is110TR  = (coursePattern=="110TTH");
is110T  = (coursePattern=="110T");
is170TR  = (coursePattern=="170TTH");
is170T   = (coursePattern=="170T");
is170R   = (coursePattern=="170R");

% patterns do not occur in our new timetable but do appear in this SP26_CourseData file
is80WF = (coursePattern=='80WF');
is110MF = (coursePattern=='110MF');
is170WF = (coursePattern=="170WF");
is110F = (coursePattern=='110F');


% CONSTRAINTS
% every class assigned exactly one slot

assignmentProb.Constraints.timeslot = sum(T,2) == ones(numCourses,1);

% capacity

assignmentProb.Constraints.capacity = classLoads - P <= M;

% student conflicts

for s = 1:numTimeSlots

    assignmentProb.Constraints.(sprintf('student%d',s)) = S*T(:,s) - A(:,s) <= uStudents;

end

%{

assignmentProb.Constraints.conflict1 = ...
    S*T(:,[1 12 13 23 24 30 31 32 33]) <= uStudents;


assignmentProb.Constraints.conflict2 = ...
    S*T(:,[2 12 13 23 24 30 31 32 33]) <= uStudents;

assignmentProb.Constraints.conflict3 = ...
    S*T(:,[2 14 15 23 24 30 31 32 33]) <= uStudents;

assignmentProb.Constraints.conflict4 = ...
    S*T(:,[3 4 5 14 15 25 26 30 31 32 33]) <= uStudents;

%?
assignmentProb.Constraints.conflict5 = ...
    S*T(:,[4 5 14 15 25 26 30 31 32 33 42 49 50 51]) <= uStudents;

assignmentProb.Constraints.conflict6 = ...
    S*T(:,[6 16 17 25 26]) <= uStudents;

assignmentProb.Constraints.conflict7 = ...
    S*T(:,[7 8 9 18 19 34 35 36 37]) <= uStudents;

assignmentProb.Constraints.conflict8 = ...
    S*T(:,[8 9 18 19 34 35 36 37 43 52 53 54]) <= uStudents;

assignmentProb.Constraints.conflict9 = ...
    S*T(:,[10 18 19 27 28 34 35 36 37]) <= uStudents;

assignmentProb.Constraints.conflict10 = ...
    S*T(:,[10 20 21 27 28 34 35 36 37]) <= uStudents;

assignmentProb.Constraints.conflict11 = ...
    S*T(:,[11 20 21 27 28 34 35 36 37]) <= uStudents;

assignmentProb.Constraints.conflict12 = ...
    S*T(:,[22 29 38 39 40]) <= uStudents;

assignmentProb.Constraints.conflict13 = ...
    S*T(:,[41 46 49 50 51]) <= uStudents;

assignmentProb.Constraints.conflict14 = ...
    S*T(:,[42 46 49 50 51]) <= uStudents;

assignmentProb.Constraints.conflict15 = ...
    S*T(:,[43 47 52 53 54]) <= uStudents;

assignmentProb.Constraints.conflict16 = ...
    S*T(:,[44 47 52 53 54]) <= uStudents;

assignmentProb.Constraints.conflict17 = ...
    S*T(:,[45 49 55 56 57]) <= uStudents;

%}

assignmentProb.Constraints.conflict1 = ...
    S*sum(T(:,[1 12 13 23 24 30 31 32 33]),2) <= uStudents;

assignmentProb.Constraints.conflict2 = ...
    S*sum(T(:,[2 12 13 23 24 30 31 32 33]),2) <= uStudents;

assignmentProb.Constraints.conflict3 = ...
    S*sum(T(:,[2 14 15 23 24 30 31 32 33]),2) <= uStudents;

assignmentProb.Constraints.conflict4 = ...
    S*sum(T(:,[3 4 5 14 15 25 26 30 31 32 33]),2) <= uStudents;


assignmentProb.Constraints.conflict5 = ...
    S*sum(T(:,[4 5 14 15 25 26 30 31 32 33 42 49 50 51]),2) <= uStudents;

assignmentProb.Constraints.conflict6 = ...
    S*sum(T(:,[6 16 17 25 26]),2) <= uStudents;

assignmentProb.Constraints.conflict7 = ...
    S*sum(T(:,[7 8 9 18 19 34 35 36 37]),2) <= uStudents;

assignmentProb.Constraints.conflict8 = ...
    S*sum(T(:,[8 9 18 19 34 35 36 37 43 52 53 54]),2) <= uStudents;

assignmentProb.Constraints.conflict9 = ...
    S*sum(T(:,[10 18 19 27 28 34 35 36 37]),2) <= uStudents;

assignmentProb.Constraints.conflict10 = ...
    S*sum(T(:,[10 20 21 27 28 34 35 36 37]),2) <= uStudents;

assignmentProb.Constraints.conflict11 = ...
    S*sum(T(:,[11 20 21 27 28 34 35 36 37]),2) <= uStudents;

assignmentProb.Constraints.conflict12 = ...
    S*sum(T(:,[22 29 38 39 40]),2) <= uStudents;

assignmentProb.Constraints.conflict13 = ...
    S*sum(T(:,[41 46 49 50 51]),2) <= uStudents;

assignmentProb.Constraints.conflict14 = ...
    S*sum(T(:,[42 46 49 50 51]),2) <= uStudents;

assignmentProb.Constraints.conflict15 = ...
    S*sum(T(:,[43 47 52 53 54]),2) <= uStudents;

assignmentProb.Constraints.conflict16 = ...
    S*sum(T(:,[44 47 52 53 54]),2) <= uStudents;

assignmentProb.Constraints.conflict17 = ...
    S*sum(T(:,[45 49 55 56 57]),2) <= uStudents;



%{
k = 1;

for i = 1:numTimeSlots-1

    for j = i+1:numTimeSlots

        if Conflict(i,j)

            assignmentProb.Constraints.(sprintf("studentConflict%d",k)) = ...
                S*T(:,i) + S*T(:,j) - A(:,i) - A(:,j) <= ones(numStudents,1);
                % S * T(:,[i,j])

            k = k + 1;

        end

    end

end
%}

% faculty conflicts


for s = 1:numTimeSlots

    assignmentProb.Constraints.(sprintf('faculty%d',s)) = F*T(:,s) - B(:,s) <= uFaculty;

end


%{
k = 1;

for i = 1:numTimeSlots-1

    for j = i+1:numTimeSlots

        if Conflict(i,j)

            assignmentProb.Constraints.(sprintf("facultyConflict%d",k)) = ...
                F*T(:,i) + F*T(:,j) - B(:,i) - B(:,j) <= ones(numFaculty,1);

            k = k + 1;

        end

    end

end
%}


% preference penalties

for s = 1:numTimeSlots

    assignmentProb.Constraints.(sprintf('preference%d',s)) = NR*T(:,s) <= 7*uStudents + psi(:,s);

end

% meeting pattern constraints (e.g. every MWF 50-minute course must choose one of these seven slots)
%{

assignmentProb.Constraints.MWF50 = ...
    T(:,[1 2 3 6 7 10 11])*ones(7,1) == is50MWF;


assignmentProb.Constraints.MTWF50 = ...
    T(:,[4 8])*ones(2,1) == is50MTWF;


assignmentProb.Constraints.MTWRF50 = ...
    T(:,[5 9])*ones(2,1) == is50MTWRF;

assignmentProb.Constraints.MW80 = ...
    T(:,[12 14 16 18 20 22])*ones(6,1) == is80MW+is80WF;

assignmentProb.Constraints.MWF80 = ...
    T(:,[13 15 17 19 21])*ones(5,1) == is80MWF;

assignmentProb.Constraints.MW110 = ...
    T(:,[23 25 27 29])*ones(4,1) == is110MW+is110MF;

assignmentProb.Constraints.MWF110 = ...
    T(:,[24 26 28])*ones(3,1) == is110MWF;

assignmentProb.Constraints.MW170 = ...
    T(:,[30 34 38])*ones(3,1) == is170MW;

assignmentProb.Constraints.M170 = ...
    T(:,[31 35 39])*ones(3,1) == is170M;

assignmentProb.Constraints.W170 = ...
    T(:,[32 36 40])*ones(3,1) == is170W;

assignmentProb.Constraints.F170 = ...
    T(:,[33 37])*ones(2,1) == is170F+is110F;

assignmentProb.Constraints.TR80 = ...
    T(:,[41 42 43 44 45])*ones(5,1) == is80TR;

assignmentProb.Constraints.TR110 = ...
    T(:,[46 47 48])*ones(3,1) == is110TR;

assignmentProb.Constraints.TR170 = ...
    T(:,[49 52 55])*ones(3,1) == is170TR;

%assignmentProb.Constraints.T170 = ...
%    T(:,[50 53 56])*ones(3,1) == is170T;

%assignmentProb.Constraints.R170 = ...
%    T(:,[51 54 57])*ones(3,1) == is170R;


assignmentProb.Constraints.TWO170 = ...
    T(:,[50 51 53 54 56 57])*ones(6,1) == is170R+is170T;

%}

% OBJECTIVE

assignmentProb.ObjectiveSense = 'minimize';

assignmentProb.Objective = 1*sum(P) + 1*sum(A,'all') + 1*sum(B,'all') + 1*sum(psi,'all');


%% Solve

opts = optimoptions('intlinprog');

[sol,fval,exitflag,output] = solve(assignmentProb,'Options',opts); %[output:04dd28c3]

disp(exitflag)
disp(fval)


Tsol = round(sol.T);

disp('T=')
disp(Tsol)



